let rectA, rectB, rectO;
let palette;

function setup() {
  createCanvas(windowWidth, windowHeight);
	frameRate(60)
  // // noLoop() removed for animation
	noStroke();
}

function init() {
	  palette = shuffle([
    "#009dff", "#ff4500", "#ffc400", "#8bc34a", "#0051ff", "#926eff",
    "#e75397", "#01b2e8", "#e8441f", "#ff6a00", "#f7a000", "#f4cd00",
    "#54ab1d", "#1b82e6", "#6d5acf", "#dddddd", "#ff437f", "#ff8f35",
    "#4dc268", "#647582", "#f6f6f6", "#028ff5", "#ff99cc", "#22d3ee",
    "#15ad03", "#ff6347", "#ffec99", "#7fff00", "#0077b6", "#b983ff",
    "#fafafa", "#ffcc00", "#3ddc84", "#004c6d", "#e6a6f5", "#ffdab9",
    "#4a90e2", "#9c27b0", "#ffead0", "#d72638", "#ffeb3b", "#2196f3",
    "#ff595e", "#ff924c", "#ffca3a", "#8ac926", "#1982c4", "#6a4c93",
    "#f72585", "#7209b7", "#3a0ca3", "#4361ee", "#4cc9f0", "#00bbf9",
    "#00f5d4", "#9ef01a", "#faff00", "#ff9f1c", "#ff4040", "#ff7f51",
    "#d00000", "#f48c06", "#e36414", "#ffbf69", "#f28482", "#cdb4db",
    "#a2d2ff", "#b5ead7", "#caffbf", "#e0fbfc", "#f1c0e8", "#e8eddf",
    "#ffe66d", "#06d6a0", "#118ab2", "#ef476f", "#ffd6e0", "#ff99c8"
  ]);
  generateRects();
}

function draw() {
	init();
  background(240);

  fill(rectA.c);
  rect(rectA.x, rectA.y, rectA.w, rectA.h);

  fill(rectB.c);
  rect(rectB.x, rectB.y, rectB.w, rectB.h);

  if (rectO) {
    fill(rectO.c);
		const dx = randomGaussian()*10;
		const dy = randomGaussian()*10;
		// console.log(`${dx}, ${dy}`);
    rect(rectO.x + dx, rectO.y + dy, rectO.w, rectO.h);
  }

	frameRate(1/2.5);
  // nextGenTime = millis() + 2500;
}

function mousePressed() {
  generateRects();
}

function generateRects() {
  const shuffled = shuffle(palette);
  rectO = null;

	rectA = {
    x: random(0, width - 200),
    y: random(0, height - 200),
    w: random(200, 500),
    h: random(200, 500),
    c: shuffled[0],
  };

	// try hard to find a corresponding overlapping rectangle
	for (let i = 0; i < 1000; i++) {
		rectB = {
			x: random(0, width - 200),
			y: random(0, height - 200),
			w: random(200, 500),
			h: random(200, 500),
			c: shuffled[1],
		};
		rectO = getOverlapRect(rectA, rectB)
		if (rectO) {
			rectO.c = shuffled[2];
			break;
		}
	}

  redraw();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function getOverlapRect(a, b) {
  const x_overlap = Math.max(0, Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x));
  const y_overlap = Math.max(0, Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y));

  if (x_overlap > 0 && y_overlap > 0) {
    return {
      x: Math.max(a.x, b.x),
      y: Math.max(a.y, b.y),
      w: x_overlap,
      h: y_overlap
    };
  } else {
    return null;
  }
}
